      const tok = run.split(/(\s+)/), words = [], seps = [];
      tok.forEach((x, i) => (i % 2 ? seps : words).push(x));
      const out = []; let i = 0;
      while (i < words.length) {
        let done = false;
        for (let n = Math.min(8, words.length - i); n >= 1 && !done; n--) {
          let ph = words.slice(i, i + n).map((w, k) => k < n - 1 ? w + seps[i + k] : w).join(''), tail = '';
          let head = '';
          const m1 = ph.match(/^[(«]+/); if (!D[ph] && m1) { head = m1[0]; ph = ph.slice(head.length); }
          const m2 = ph.match(/[،.:)»]+$/); if (!D[ph] && m2) { tail = m2[0]; ph = ph.slice(0, -tail.length); }
          if (D[ph]) { out.push(head + D[ph][c] + tail); i += n; done = true; }
        }
        if (!done) { out.push(words[i]); i++; }
        if (i < words.length) out.push(seps[i - 1] ?? ' ');
      }
